export default function prepareUrls({ urlsJson }) {
  let raw;
  try {
    raw = JSON.parse(urlsJson);
  } catch {
    throw new Error("Page URLs must be a JSON array.");
  }
  if (!Array.isArray(raw)) throw new Error("Page URLs must be a JSON array.");
  const urls = raw.slice(0, 40).map((url) => {
    if (typeof url !== "string" || !/^https?:\/\/[^\s/]+(?:\/[^\s]*)?$/i.test(url.trim()))
      throw new Error("Each selected page needs a nonempty HTTP or HTTPS URL.");
    return url.trim();
  });
  return { urls, inputCount: raw.length, skippedCount: Math.max(raw.length - 40, 0) };
}

