import { setTimeout as delay } from "node:timers/promises";

export async function scrapePages({ urls }, context, wait = delay) {
  const pages = [];
  for (let index = 0; index < urls.length; index++) {
    context.signal?.throwIfAborted();
    const result = await context.workflows.call("scrape-one-page", { url: urls[index] });
    if (result?.page?.url !== urls[index])
      throw new Error("The page result belongs to a different source URL.");
    pages.push(result.page);
    if ((index + 1) % 10 === 0 && index + 1 < urls.length)
      await wait(60000, undefined, { signal: context.signal });
  }
  return { pages, processedCount: pages.length };
}
export default async function run(input, context) {
  return scrapePages(input, context);
}

