export default function readPage({ url, result }) {
  if (
    !result ||
    result.success !== true ||
    !result.data ||
    typeof result.data !== "object" ||
    Array.isArray(result.data)
  )
    throw new Error("Firecrawl did not return a successful page scrape.");
  const data = result.data;
  if (
    typeof data.markdown !== "string" ||
    !Array.isArray(data.links) ||
    data.links.some((link) => typeof link !== "string")
  )
    throw new Error("Firecrawl omitted the requested Markdown or link array.");
  const text = (value) =>
    value == null
      ? ""
      : typeof value === "string"
        ? value
        : (() => {
            throw new Error("Page metadata must be text when present.");
          })();
  const status = data.metadata?.statusCode;
  return {
    page: {
      url,
      title: text(data.metadata?.title),
      description: text(data.metadata?.description),
      content: data.markdown,
      links: data.links,
      pageStatus: Number.isInteger(status) && status >= 100 && status <= 599 ? status : null,
    },
  };
}
